import json, glob
print('=== Looking for obs_only seed45 files ===')
patterns = [
    '/root/acr-vla-conformal-refinement/logs/eval_object*obs_only*seed45*.json',
    '/root/acr-vla-conformal-refinement/logs/*obs_only*seed45*.json',
    '/root/acr-vla-conformal-refinement/logs/*obs*only*seed45*.json',
]
found = set()
for p in patterns:
    found.update(glob.glob(p))
if not found:
    all_files = glob.glob('/root/acr-vla-conformal-refinement/logs/*seed45*.json')
    print(f'No obs_only seed45 files. All seed45 JSONs: {all_files}')
    all_logs = glob.glob('/root/acr-vla-conformal-refinement/logs/*.json')
    recent = sorted(all_logs, key=lambda x: __import__('os').path.getmtime(x), reverse=True)[:10]
    print(f'Recent 10 JSONs: {[__import__(\"os\").path.basename(f) for f in recent]}')
else:
    for f in sorted(found):
        print(f'FILE: {f}')
        data = json.load(open(f))
        print(f'  type={type(data).__name__}, keys={list(data.keys()) if isinstance(data, dict) else len(data)}')
        if isinstance(data, dict):
            if 'overall_sr' in data:
                print(f'  overall_sr={data[\"overall_sr\"]}, successes={data.get(\"successes\")}, total={data.get(\"total\")}')
            elif 'success_rate' in data:
                print(f'  success_rate={data[\"success_rate\"]}')
            else:
                total = 0
                success = 0
                for k, v in data.items():
                    if isinstance(v, list):
                        total += len(v)
                        success += sum(1 for r in v if (r.get('success', False) if isinstance(r, dict) else r))
                    elif isinstance(v, (int, float)):
                        print(f'  {k}={v}')
                if total > 0:
                    print(f'  computed: total={total}, success={success}, sr={success/total:.4f}')
                print(f'  preview: {json.dumps(data)[:800]}')
"

